list_tax_rules.code:
final response = await client.taxRules.listTaxRules(queryParams: {'limit': 20});
final taxRules = (response.map as Map)['tax_rules'] as List;
for (final taxRule in taxRules) {
  print('${(taxRule as Map)['id']} ${taxRule['name']} ${taxRule['zones']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print(pagination['total']);

create_tax_rule.code:
final response = await client.taxRules.createTaxRule({
  'tax_rule': {
    'name': 'Reduced rate',
    'description': 'Rule for reduced-rate goods',
  },
});
final taxRule = (response.map as Map)['tax_rule'] as Map;
print(taxRule['id']);

